  'landing.proNext5': 'Seismic workflows to INPRES-CIRSOC 103.',
  'landing.proHonest': 'In practice: a real drawing set and a real bar schedule come out of Stabileo today for beams, columns, footings, slabs and walls, and they are worth reviewing. Complete, building-wide documentation is the next step, and every result carries how far its validation has gone.',
  'landing.cirsocP': 'Stabileo is built in Argentina, so CIRSOC comes first: it is the Argentine regulatory framework and the one this work answers to, and it is where code-based design is furthest along. The roadmap continues with the Eurocodes, and then with the United States codes.',
  'landing.cir101Scope': 'Permanent and imposed loads, and load combinations',
  'landing.cir101Body': 'Generated from the model: self weight, partition allowance, the minimum imposed loads of Table 4.1, live-load reduction, and the seven strength combinations verbatim.',
  'landing.cir101Limit': 'Further load types will follow.',
  'landing.cir102Scope': 'Wind action',
  'landing.cir102Body': 'Velocity pressure, exposure and terrain constants, topography, gust effect, enclosure classification and the wall and roof pressure coefficients, applied to the main wind-force resisting system.',
  'landing.cir102Limit': 'Non-rigid buildings and torsional load cases will be added.',
  'landing.cir201Scope': 'Reinforced-concrete design, and reinforcement generation',
  'landing.cir201Body': 'The strongest coverage of any code here. Beams and columns are both verified and generated: flexure, shear, ties, bar regions, spacing, anchorage and lap lengths, each result carrying its clause. Slabs, walls and pad footings are designed too, reachable from the workflow, and their results are labelled provisional.',
  'landing.cir201Limit': 'Finishing development, and being tested against real projects.',
  'landing.cir301Scope': 'Steel member checking',
  'landing.cir301Body': 'A checker for steel members on the AISC 360 LRFD basis: tension, compression, flexure with lateral-torsional buckling, shear and combined actions.',
  'landing.cir301Limit': 'Code-based design in development.',
  'landing.cir103Scope': 'Seismic action and seismic detailing',
  'landing.cir103Body': 'Effective seismic weight and the static-method distribution of base shear up the height are already generated.',
  'landing.cir103Limit': 'Code-based seismic workflow in development.',
  'landing.codesIntlTitle': 'INTERNATIONAL CODES · MEMBER CHECKING',
