  'tooltip.toolSelect.title': 'Select (V)',
  'tooltip.toolSelect.desc': 'Has 5 sub-modes: Nodes, Elements, Supports, Loads, and Stresses. Switch in the floating bar.',
  'tooltip.toolNode.title': 'Create Node (N)',
  'tooltip.toolNode.desc': 'Click on the canvas to place a junction point. Nodes are where members connect and loads are applied.',
  'tooltip.toolElement.title': 'Create Element (E)',
  'tooltip.toolElement.desc': 'Click a start node, then an end node. A member is created between them. Frame = rigid, Truss = pinned.',
  'tooltip.toolSupport.title': 'Create Support (S)',
  'tooltip.toolSupport.desc': 'Click on a node to place a support. The support type determines which movements are restrained.',
  'tooltip.toolLoad.title': 'Apply Load (L)',
  'tooltip.toolLoad.desc': 'Click on a node (point load) or member (distributed load) to apply a force. Negative values = downward.',
  'tooltip.toolInfluence.title': 'Influence Line (I)',
  'tooltip.toolInfluence.desc': 'Shows how a reaction or force varies when a unit load traverses the structure.',
  'tooltip.toolPan.title': 'Pan View (H)',
  'tooltip.toolPan.desc': 'Drag to move the view. You can also use middle-click or Ctrl+drag.',
  'tooltip.solve.title': 'Solve',
  'tooltip.solve.desc': 'Solves the structure using the Direct Stiffness Method (DSM). Requires nodes, members, supports, and loads.',
  'tooltip.selfweight.title': 'Self-Weight',
  'tooltip.selfweight.desc': 'Automatically adds gravity distributed loads using the material density and section area.',
  'tooltip.diagNone.title': 'No Diagram',
  'tooltip.diagNone.desc': 'Hides all result diagrams. Only the structure is shown.',
  'tooltip.diagDeformed.title': 'Deformed Shape',
  'tooltip.diagDeformed.desc': 'Shows the amplified deformed shape. Useful for verifying that the behavior is reasonable.',
  'tooltip.diagMoment.title': 'Bending Moment (M)',
  'tooltip.diagMoment.desc': 'Diagram of the bending moment in each member. Drawn on the tension side by convention.',
  'tooltip.diagShear.title': 'Shear (V)',
  'tooltip.diagShear.desc': 'Diagram of shear force along each member. Abrupt changes indicate point loads.',
  'tooltip.diagAxial.title': 'Axial (N)',
  'tooltip.diagAxial.desc': 'Diagram of axial force. Positive = tension (member stretches), negative = compression.',
  'tooltip.diagAxialColor.title': 'Axial Color (N\u00B1)',
  'tooltip.diagAxialColor.desc': 'Colors members by axial force: red = tension, blue = compression. Thickness proportional to magnitude.',
  'tooltip.diagColorMap.title': 'Color Map',
  'tooltip.diagColorMap.desc': 'Colors members by the selected force (moment, shear, axial, or \u03C3/fy ratio) using a color scale.',
  'tooltip.supFixed.title': 'Fixed',
  'tooltip.supFixed.desc': 'Restrains horizontal displacement (ux), vertical (uy), and rotation (\u03B8). No movement allowed.',
  'tooltip.supPinned.title': 'Pinned',
  'tooltip.supPinned.desc': 'Restrains ux and uy, but allows rotation. The member can rotate freely at this point.',
  'tooltip.supRollerX.title': 'Roller X',
  'tooltip.supRollerX.desc': 'Only restrains uy (vertical). Allows horizontal movement and rotation. Typical "roller" support.',
  'tooltip.supRollerY.title': 'Roller Y',
  'tooltip.supRollerY.desc': 'Only restrains ux (horizontal). Allows vertical movement and rotation.',
  'tooltip.supSpring.title': 'Spring',
  'tooltip.supSpring.desc': 'Elastic support with configurable stiffness in each direction (kx, ky, k\u03B8). Models soil or flexible connections.',

